∀ {R : Type u_3} [inst : CommRing R] {ι : Type u_1} [inst_1 : Finite ι] {B : ι → Type u_2}
  [inst_2 : (i : ι) → CommRing (B i)] [inst_3 : (i : ι) → Algebra R (B i)]
  (x x_1 : ↥(integralClosure R ((i : ι) → B i))), (fun i => ⟨↑(x + x_1) i, ⋯⟩) = fun i => ⟨↑(x + x_1) i, ⋯⟩

∀ {R : Type u_1} [inst : CommRing R] {ι : Type u_2} [inst_1 : Finite ι] {B : ι → Type u_3}
  [inst_2 : (i : ι) → CommRing (B i)] [inst_3 : (i : ι) → Algebra R (B i)] (x : ↥(integralClosure R ((i : ι) → B i))),
  IsIntegral R fun i => ↑⟨↑x i, ⋯⟩

∀ {R : Type u_3} [inst : CommRing R] {ι : Type u_1} [inst_1 : Finite ι] {B : ι → Type u_2}
  [inst_2 : (i : ι) → CommRing (B i)] [inst_3 : (i : ι) → Algebra R (B i)] (x : ↥(integralClosure R ((i : ι) → B i))),
  ⟨fun i => ↑⟨↑x i, ⋯⟩, ⋯⟩ = ⟨fun i => ↑⟨↑x i, ⋯⟩, ⋯⟩

∀ {R : Type u_1} [inst : CommRing R] {ι : Type u_3} [inst_1 : Finite ι] {B : ι → Type u_2}
  [inst_2 : (i : ι) → CommRing (B i)] [inst_3 : (i : ι) → Algebra R (B i)] (x : (i : ι) → ↥(integralClosure R (B i)))
  (i : ι), IsIntegral R (↑⟨fun i => ↑(x i), ⋯⟩ i)

∀ {R : Type u_2} [inst : CommRing R] {ι : Type u_3} [inst_1 : Finite ι] {B : ι → Type u_1}
  [inst_2 : (i : ι) → CommRing (B i)] [inst_3 : (i : ι) → Algebra R (B i)] (x : (i : ι) → ↥(integralClosure R (B i))),
  (fun i => ⟨↑⟨fun i => ↑(x i), ⋯⟩ i, ⋯⟩) = fun i => ⟨↑⟨fun i => ↑(x i), ⋯⟩ i, ⋯⟩

∀ {R : Type u_3} [inst : CommRing R] {ι : Type u_1} [inst_1 : Finite ι] {B : ι → Type u_2}
  [inst_2 : (i : ι) → CommRing (B i)] [inst_3 : (i : ι) → Algebra R (B i)]
  (x x_1 : ↥(integralClosure R ((i : ι) → B i))), (fun i => ⟨↑(x * x_1) i, ⋯⟩) = fun i => ⟨↑(x * x_1) i, ⋯⟩
